def subtract(a, b):
    # Filter out empty intervals and sort
    a_valid = sorted([interval for interval in a if interval[0] < interval[1]])
    b_valid = sorted([interval for interval in b if interval[0] < interval[1]])

    if not a_valid:
        return []

    if not b_valid:
        return a_valid

    # Merge overlapping intervals in both lists
    def merge_intervals(intervals):
        if not intervals:
            return []
        merged = [intervals[0]]
        for start, end in intervals[1:]:
            if start <= merged[-1][1]:
                merged[-1][1] = max(merged[-1][1], end)
            else:
                merged.append([start, end])
        return merged

    a_merged = merge_intervals(a_valid)
    b_merged = merge_intervals(b_valid)

    result = []

    for a_start, a_end in a_merged:
        current_ranges = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            next_ranges = []
            for curr_start, curr_end in current_ranges:
                # No overlap
                if curr_end <= b_start or curr_start >= b_end:
                    next_ranges.append([curr_start, curr_end])
                else:
                    # There is overlap, keep parts outside b interval
                    if curr_start < b_start:
                        next_ranges.append([curr_start, b_start])
                    if curr_end > b_end:
                        next_ranges.append([b_end, curr_end])
            current_ranges = next_ranges

        result.extend(current_ranges)

    # Merge touching intervals in result
    if not result:
        return []

    result.sort()
    merged_result = [result[0]]
    for start, end in result[1:]:
        if start <= merged_result[-1][1]:
            merged_result[-1][1] = max(merged_result[-1][1], end)
        else:
            merged_result.append([start, end])

    return merged_result

